const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Články</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Německý článek se ne vždy shoduje s českým rodem. Podstatná jména se proto nejlépe učí společně se členem.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Příklady článků</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Der Tisch - stol</div>\n      <div class=\"kurss-example\">Die Tür - dveře</div>\n      <div class=\"kurss-example\">Das Messer - nůž</div>\n      <div class=\"kurss-example\">Das Mädchen - dívka</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Často DER</h4>\n    <p class=\"artikuli-explain\">DER jsou často mužské osoby, dny, měsíce, roční období a některá slova s ​​určitými konci.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravidla</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → bieži DER, piemēram: der Computer, der Lehrer <span class=\"artikuli-note\">Ale ne vždy</span></div>\n      <div class=\"kurss-example\">-ling → často DER, např.: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → často DER, např.: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">Mužské osoby → der Mann, der Vater</div>\n      <div class=\"kurss-example\">Profese → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">Značky aut → pasuje na BMW, pasuje na Mercedes</div>\n      <div class=\"kurss-example\">Dny → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">Měsíce → der August, der Dezember</div>\n      <div class=\"kurss-example\">Roční období → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Příklady</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Der Mann - muž</div>\n      <div class=\"kurss-example\">Der Vater - otec</div>\n      <div class=\"kurss-example\">Der Montag — pondělí</div>\n      <div class=\"kurss-example\">Srpen — srpen</div>\n      <div class=\"kurss-example\">Der Sommer — léto</div>\n      <div class=\"kurss-example\">Der Lehrer - učitel</div>\n      <div class=\"kurss-example\">Der Computer - počítač</div>\n      <div class=\"kurss-example\">Der Schmetterling - motýl</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Často UMŘI</h4>\n    <p class=\"artikuli-explain\">DIE je často ženského rodu, množného čísla a slova končí na -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravidla</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion→ zemřít národ</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">Ženské osoby → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">Motocyklové značky → Harley-Davidson, Yamaha</div>\n      <div class=\"kurss-example\">Množné číslo → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">Množné číslo téměř vždy → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Příklady</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Die Frau - žena</div>\n      <div class=\"kurss-example\">Die Mutter - matka</div>\n      <div class=\"kurss-example\">Die Wohnung - byt</div>\n      <div class=\"kurss-example\">Die Rechnung - účet</div>\n      <div class=\"kurss-example\">Die Freiheit – svoboda</div>\n      <div class=\"kurss-example\">Die Möglichkeit - možnost</div>\n      <div class=\"kurss-example\">Die Mannschaft - tým</div>\n      <div class=\"kurss-example\">Die Nation — národ</div>\n      <div class=\"kurss-example\">Die Universität - univerzita</div>\n      <div class=\"kurss-example\">Die Polizei – policie</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Často DAS</h4>\n    <p class=\"artikuli-explain\">DAS mají často zdrobněliny s -chen / -lein, mnoho slov s -ment / -um a slovesa jako podstatná jména.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravidla</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">Kovy → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">Chemické prvky → das Eisen, das Sauerstoff</div>\n      <div class=\"kurss-example\">Hotely → das Hotel</div>\n      <div class=\"kurss-example\">Barvy jako podstatná jména → das Rot, das Blau</div>\n      <div class=\"kurss-example\">Sloveso jako podstatné jméno → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">Slovesa jako podstatná jména → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Příklady</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Das Kind - dítě</div>\n      <div class=\"kurss-example\">Das Mädchen - dívka</div>\n      <div class=\"kurss-example\">Das Häuschen - chata</div>\n      <div class=\"kurss-example\">Das Instrument - nástroj</div>\n      <div class=\"kurss-example\">Das Zentrum — střed</div>\n      <div class=\"kurss-example\">Das Museum — muzeum</div>\n      <div class=\"kurss-example\">Das Essen - stravování / jídlo</div>\n      <div class=\"kurss-example\">Das Lernen - učení</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Důležité výjimky / nutno se naučit s článkem</h4>\n    <p class=\"artikuli-explain\">U některých slov nelze článek spolehlivě určit podle koncovky nebo českýé rodiny. Nejlépe se studují společně s článkem.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">Die Tür - dveře</div>\n      <div class=\"kurss-example\">Das Messer - nůž</div>\n      <div class=\"kurss-example\">Die Sonne — slunce</div>\n      <div class=\"kurss-example\">Der Mond — měsíc</div>\n      <div class=\"kurss-example\">Das Mädchen - dívka</div>\n      <div class=\"kurss-example\">Das Auto - auto</div>\n      <div class=\"kurss-example\">Der Käse - sýr</div>\n      <div class=\"kurss-example\">Die Gabel - vidlice</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Koncovky a skupiny slov pomáhají uhodnout článek, ale nejsou 100% jistým pravidlem. Pokud si nejste jisti, naučte se slovo s článkem.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Zájmena</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, akuzativ a dativ – tvary zájmen.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ – kdo? co?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich – já</div><div class=\"kurss-example\">Du – ty</div><div class=\"kurss-example\">Er – on</div><div class=\"kurss-example\">Sie – ona</div><div class=\"kurss-example\">Es – ono</div><div class=\"kurss-example\">Wir – my</div><div class=\"kurss-example\">Ihr – vy</div><div class=\"kurss-example\">Sie – oni / ony / ona</div><div class=\"kurss-example\">Sie – Vy (zdvořilé oslovení)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ – koho? co?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Mich – mě</div><div class=\"kurss-example\">Dich – tě</div><div class=\"kurss-example\">Ihn – ho</div><div class=\"kurss-example\">Sie – ji</div><div class=\"kurss-example\">Es – ho</div><div class=\"kurss-example\">Uns – nás</div><div class=\"kurss-example\">Euch – vás</div><div class=\"kurss-example\">Sie – je</div><div class=\"kurss-example\">Sie – Vás (zdvořilé oslovení)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ – komu? čemu?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Mir – mně</div><div class=\"kurss-example\">Dir – tobě</div><div class=\"kurss-example\">Ihm – jemu</div><div class=\"kurss-example\">Ihr – jí</div><div class=\"kurss-example\">Ihm – jemu</div><div class=\"kurss-example\">Uns – nám</div><div class=\"kurss-example\">Euch – vám</div><div class=\"kurss-example\">Ihnen – jim</div><div class=\"kurss-example\">Ihnen – Vám (zdvořilé oslovení)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Jak vybrat formu?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> – podmět věty (kdo? co?)</li><li><span class=\"case-red\">Akuzativ</span> – přímý předmět (koho? co?)</li><li><span class=\"case-green\">Dativ</span> – nepřímý předmět (komu? čemu?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Příklady</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Vidím tě.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Vidím ho.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Máme vás rádi.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Pomáhám ti.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Dávám mu knihu.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Děkujeme vám.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ je zpravidla podmět věty. Akuzativ označuje přímý předmět a dativ nepřímý předmět. Ptej se: koho? co? nebo komu? čemu?</div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Samohlásky - dlouhé a krátké</h3>\n            <p class=\"kurss-lesson-intro\">V němčině mohou být samohlásky dlouhé nebo krátké. To má vliv na výslovnost slova.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dlouhá samohláska</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Warm (varm) — teplý</div><div class=\"kurss-example\">Gut (gút) — dobrý</div><div class=\"kurss-example\">Tat (tát) — čin / skutek</div><div class=\"kurss-example\">Flur (flūr) - chodba</div><div class=\"kurss-example\">Weg (vék) — cesta</div><div class=\"kurss-example\">Hut (hūt) - klobouk</div><div class=\"kurss-example\">Hof (hōf) - dvůr</div><div class=\"kurss-example\">Schlaf (šláf) — spánek</div></div>\n              <p>Pokud za samohláskou následuje jedna souhláska, samohláska se často vyslovuje dlouze.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Krátká samohláska</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilc) - houba</div><div class=\"kurss-example\">Wort (vort) - slovo</div><div class=\"kurss-example\">Mund (munt) - ústa</div><div class=\"kurss-example\">Bald (balt) — brzy</div><div class=\"kurss-example\">Scharf (šarf) — ostrý</div><div class=\"kurss-example\">Feld (felt) — pole</div><div class=\"kurss-example\">Voll (fol) - plný</div></div>\n              <p>Když za samohláskou následují dvě nebo více souhlásek, samohláska se často vyslovuje krátce.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Koncovky en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Singen (zingen) - zpívat</div><div class=\"kurss-example\">Tragen (trágen) — nést</div><div class=\"kurss-example\">Garten (garten) - zahrada</div><div class=\"kurss-example\">Vogel (fogel) - pták</div><div class=\"kurss-example\">Segel (zégel) — plachta</div><div class=\"kurss-example\">Braten (bráten) — pečeně</div><div class=\"kurss-example\">Bogen (bōgen) - luk</div><div class=\"kurss-example\">Spiegel (špígel) — zrcadlo</div><div class=\"kurss-example\">Finger (finger) — prst</div><div class=\"kurss-example\">Halter (halter) — držák</div><div class=\"kurss-example\">Arbeiter (arbaiter) - dělník</div><div class=\"kurss-example\">Häuser (hoizer) - domy</div><div class=\"kurss-example\">Wieder (víder) — znovu</div><div class=\"kurss-example\">Breiter (braiter) - širší</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Písmeno h jako označení délky samohlásky</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rámen) — rám</div><div class=\"kurss-example\">Ohr (ōr) — ucho</div><div class=\"kurss-example\">Kohle (kōle) - uhlí</div><div class=\"kurss-example\">Zahl (cál) — číslo</div><div class=\"kurss-example\">Ihn (ín) — ho / jej</div><div class=\"kurss-example\">Ihm (īm) — jemu</div><div class=\"kurss-example\">Huhn (hūn) - kuře</div><div class=\"kurss-example\">Nahm (nām) — vzal</div><div class=\"kurss-example\">Nehmen (nēmen) — vzít</div><div class=\"kurss-example\">Schuh (šú) — bota</div></div>\n              <p>V některých slovech h prodlužuje předchozí samohlásku. V takových případech je h obvykle nevyslovováno.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Koncovky na e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampa</div><div class=\"kurss-example\">Hase (háze) — zajíc</div><div class=\"kurss-example\">Knabe (knábe) — chlapec</div><div class=\"kurss-example\">Rabe (rábe) — havran</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dlouhé i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Die (dí) — určitý člen „die“</div><div class=\"kurss-example\">Diese (díze) — tato / tito / tyto</div><div class=\"kurss-example\">Wieder - znovu</div><div class=\"kurss-example\">Fliege (flíge) — moucha</div><div class=\"kurss-example\">Ziege (tsīge) - koza</div><div class=\"kurss-example\">Stiel (štíl) — stonek / násada</div><div class=\"kurss-example\">Dieb (díp) — zloděj</div><div class=\"kurss-example\">Hier (hīr) — zde</div></div>\n              <p>Dlouhé i se v němčině často píše jako ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhlásky</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zál) — sál</div><div class=\"kurss-example\">Saat (zát) — setí</div><div class=\"kurss-example\">Staat (štát) — stát</div><div class=\"kurss-example\">Pivo (pohřební) - bobule</div><div class=\"kurss-example\">Viz (zee) - jezero / moře</div><div class=\"kurss-example\">Řepa (бет) - postel</div><div class=\"kurss-example\">Boot (bōt) - člun</div><div class=\"kurss-example\">Moor (mōr) - bažina</div><div class=\"kurss-example\">Moos (mōs) - mech</div></div>\n              <p>Německé dvojhlásky se vyslovují jako spojení dvou samohláskových zvuků v jedné slabice.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Hůlka (vant) — stěna</div><div class=\"kurss-example\">Wände (vende) - stěny</div><div class=\"kurss-example\">Vater (fátr) — otec</div><div class=\"kurss-example\">Väter (fēter) - otcové</div><div class=\"kurss-example\">Schrank (šrank) — skříň</div><div class=\"kurss-example\">Schränke (šrénke) — skříně</div><div class=\"kurss-example\">Bank (bank) - lavička / banka</div><div class=\"kurss-example\">Bänke (benke) - krok</div><div class=\"kurss-example\">Tal (tál) — údolí</div><div class=\"kurss-example\">Täler (tēler) - údolí</div></div>\n              <p>Ä je přehláska písmene a. Vyslovuje se podobně jako české e.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) - růže</div><div class=\"kurss-example\">Röschen (röšen) — růžička</div><div class=\"kurss-example\">Ofen (ōfen) - trouba</div><div class=\"kurss-example\">Öfen (öfen) - pece</div><div class=\"kurss-example\">Rock (rok) - sukně</div><div class=\"kurss-example\">Röcke (röke) - sukně</div></div>\n              <p>Ö je přehláska písmene o. Vyslovuje se podobně jako české e, ale se zaokrouhlenými rty.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Kurz (kurc) — krátký</div><div class=\"kurss-example\">Kürzer (kürcer) — kratší</div><div class=\"kurss-example\">Kunst (kunst) — umění</div><div class=\"kurss-example\">Künste (künste) — umění</div><div class=\"kurss-example\">Mutter (muter) - matka</div><div class=\"kurss-example\">Mütter (müter) — matky</div></div>\n              <p>Ü je německá přehláska u. Vyslovuje se s jazykem v poloze podobné českému i a se zaokrouhlenými rty.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhlásky: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) - strom</div><div class=\"kurss-example\">Bäume (boime) - stromy</div><div class=\"kurss-example\">Haus (haus) — dům</div><div class=\"kurss-example\">Häuser (hoizer) - domy</div><div class=\"kurss-example\">Strauch (štrauch; ch jako v německém Ach) — keř</div><div class=\"kurss-example\">Sträucher (štroichr; ch jako německé Ich-Laut) — keře</div><div class=\"kurss-example\">Maus (maus) - myš</div><div class=\"kurss-example\">Mäuse (moize) — myši</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhlásky: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Heute (hoite) - dnes</div><div class=\"kurss-example\">Leute (loite) – lidé</div><div class=\"kurss-example\">Neu (noi) - nový</div><div class=\"kurss-example\">Neun (noin) - devět</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dvojhláska ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Mein (main) — můj</div><div class=\"kurss-example\">Dein (dain) — tvůj</div><div class=\"kurss-example\">Sein (zain) — jeho / být</div><div class=\"kurss-example\">Frei (frai) - zdarma</div><div class=\"kurss-example\">Arbeiten (arbaiten) - pracovat</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Poznámky k výslovnosti z lekce 2</h4>\n              <ul class=\"kurss-summary-list\"><li>Ve slovech ich, nicht, rechnen, zeichnen se „ch“ vyslovuje měkce</li><li>V arbeiten a zeichnen se „ei“ vyslovuje jako „ai“</li><li>\"sp\" na začátku slova se vyslovuje jako \"šp\"</li><li>Ve slově tun se samohláska „u“ vyslovuje dlouze.</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Shrnutí</h4>\n              <ul class=\"kurss-summary-list\"><li>Jedna souhláska po samohlásce → často dlouhá samohláska</li><li>Dvě a více souhlásek → často krátká samohláska</li><li>H může prodloužit samohlásku</li><li>„ie“ často označuje dlouhé i.</li><li>Dvojhlásky se vyslovují jako spojení dvou samohláskových zvuků v jedné slabice.</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Souhlásky a kombinace písmen</h3>\n            <p class=\"kurss-lesson-intro\">V němčině se některé souhlásky a kombinace písmen vyslovují jinak, než se píší. Tato přednáška obsahuje nejdůležitější příklady pro začátečníky.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Souhlásky</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Das Rad (rāt) — kolo</div><div class=\"kurss-example\">Die Räder (réder) — kola</div><div class=\"kurss-example\">Bad (bāt) – koupel</div><div class=\"kurss-example\">Bäder (béder) — koupele</div></div>\n              <p>Na konci slova se v němčině znělé souhlásky b, d a g obvykle vyslovují nezněle jako p, t a k.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ch</h4>\n              <p>Německé „ch“ má dvě hlavní výslovnosti: měkké [ç] a tvrdé [x]. Tvrdé [x] se podobá českému „ch“, zatímco měkké [ç] se vyslovuje více vpředu v ústech.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rechnen (rehnen) - vypočítat</div><div class=\"kurss-example\">Zeichnen (caihnen) - kreslit</div><div class=\"kurss-example\">Nicht (niht) - ne</div><div class=\"kurss-example\">Schlecht (šleht) - špatný</div><div class=\"kurss-example\">Mich (mih) — mě / mne</div><div class=\"kurss-example\">Dich (dih) — tebe / tě</div><div class=\"kurss-example\">Strauch (štrauh) - keř</div><div class=\"kurss-example\">Noch (noch) — ještě</div><div class=\"kurss-example\">Nacht (nacht) — noc</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sch</h4>\n              <p>„sch“ se v němčině vyslovuje jako české „š“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule - škola</div><div class=\"kurss-example\">Schüler (šüler) — žák</div><div class=\"kurss-example\">Schiff (šif) - loď</div><div class=\"kurss-example\">Schraube (šraube) — šroub</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sp a st na začátku slova</h4>\n              <p>Na začátku slova nebo slabiky se „sp“ často vyslovuje jako „šp“ a „st“ jako „št“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielen (špīlen) - hrát si</div><div class=\"kurss-example\">Sprung (šprung) — skok</div><div class=\"kurss-example\">Stehen (štéen) — stát</div><div class=\"kurss-example\">Stall (štal) — stáj</div><div class=\"kurss-example\">Stand (štant) — pozice / místo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Qu</h4>\n              <p>„qu“ se v němčině obvykle vyslovuje jako „kv“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) - muka</div><div class=\"kurss-example\">Quartier (kvartýr) — čtvrť / ubytování</div><div class=\"kurss-example\">Quer (kvér) — napříč</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>S a z</h4>\n              <p>„S“ na začátku slova často zní jako „z“. Písmeno „z“ v němčině zní jako české „c“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Sagen (zágen) — říci</div><div class=\"kurss-example\">Singen (zingen) - zpívat</div><div class=\"kurss-example\">Rose (rōze) - růže</div><div class=\"kurss-example\">Zahl (cál) — číslo</div><div class=\"kurss-example\">Zeit (cait) - čas</div><div class=\"kurss-example\">Zink (cink) - zinek</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>V němčině se „v“ často vyslovuje jako „f“. V cizích slovech často zní jako české „v“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fátr) — otec</div><div class=\"kurss-example\">Von (fon) — od</div><div class=\"kurss-example\">Viel (fīl) — hodně</div><div class=\"kurss-example\">Vier (fīr) — čtyři</div><div class=\"kurss-example\">Vila (vila) - vila</div><div class=\"kurss-example\">Klavier (klavír) - klavír</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>X a y</h4>\n              <p>\"x\" se vyslovuje jako \"ks\". \"y\" se v některých slovech vyslovuje jako \"ü\".</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (féliks) — Felix</div><div class=\"kurss-example\">Axt (akst) - sekera</div><div class=\"kurss-example\">Mystik (müstik) — mystika</div><div class=\"kurss-example\">Nyx - Nix</div><div class=\"kurss-example\">Mythe (müte) — mýtus</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>„ß“ se v němčině vyslovuje jako „s“.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß - noha</div><div class=\"kurss-example\">Füße (füse) - nohy</div><div class=\"kurss-example\">Grüße - pozdravy</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Shrnutí</h4>\n              <ul class=\"kurss-summary-list\"><li>Sch → š</li><li>Sp / st na začátku → šp / št</li><li>Qu → kv</li><li>Z → c</li><li>V často → f</li><li>X → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Základy sloves</h3>\n            <p class=\"kurss-lesson-intro\">Slovesa a časování z 1. lekce.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Slovesa</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — přicházet</div><div class=\"kurss-example\">gehen — jít</div><div class=\"kurss-example\">stehen — stát</div><div class=\"kurss-example\">singen — zpívat</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — přicházím</div><div class=\"kurss-example\">du kommst — přicházíš</div><div class=\"kurss-example\">er kommt — přichází</div><div class=\"kurss-example\">sie kommt — přichází</div><div class=\"kurss-example\">wir kommen — přicházíme</div><div class=\"kurss-example\">ihr kommt — přicházíte</div><div class=\"kurss-example\">sie kommen — přicházejí</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — jdu</div><div class=\"kurss-example\">du gehst — jdeš</div><div class=\"kurss-example\">er geht — jde</div><div class=\"kurss-example\">sie geht — jde</div><div class=\"kurss-example\">wir gehen — jdeme</div><div class=\"kurss-example\">ihr geht — jdete</div><div class=\"kurss-example\">sie gehen — jdou</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — stojím</div><div class=\"kurss-example\">du stehst — stojíš</div><div class=\"kurss-example\">er steht — stojí</div><div class=\"kurss-example\">sie steht — stojí</div><div class=\"kurss-example\">wir stehen — stojíme</div><div class=\"kurss-example\">ihr steht — stojíte</div><div class=\"kurss-example\">sie stehen — stojí</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — zpívám</div><div class=\"kurss-example\">du singst — zpíváš</div><div class=\"kurss-example\">er singt — zpívá</div><div class=\"kurss-example\">sie singt — zpívá</div><div class=\"kurss-example\">wir singen — zpíváme</div><div class=\"kurss-example\">ihr singt — zpíváte</div><div class=\"kurss-example\">sie singen — zpívají</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Slovesa z 2. lekce</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — hrát</div><div class=\"kurss-example\">arbeiten — pracovat</div><div class=\"kurss-example\">fragen — ptát se</div><div class=\"kurss-example\">antworten — odpovídat</div><div class=\"kurss-example\">rechnen — počítat</div><div class=\"kurss-example\">zeichnen — kreslit</div><div class=\"kurss-example\">tun — dělat</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — hraji</div><div class=\"kurss-example\">du spielst — hraješ</div><div class=\"kurss-example\">er spielt — hraje</div><div class=\"kurss-example\">sie spielt — hraje</div><div class=\"kurss-example\">wir spielen — hrajeme</div><div class=\"kurss-example\">ihr spielt — hrajete</div><div class=\"kurss-example\">sie spielen — hrají</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — pracuji</div><div class=\"kurss-example\">du arbeitest — pracuješ</div><div class=\"kurss-example\">er arbeitet — pracuje</div><div class=\"kurss-example\">sie arbeitet — pracuje</div><div class=\"kurss-example\">wir arbeiten — pracujeme</div><div class=\"kurss-example\">ihr arbeitet — pracujete</div><div class=\"kurss-example\">sie arbeiten — pracují</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — ptám se</div><div class=\"kurss-example\">du fragst — ptáš se</div><div class=\"kurss-example\">er fragt — ptá se</div><div class=\"kurss-example\">sie fragt — ptá se</div><div class=\"kurss-example\">wir fragen — ptáme se</div><div class=\"kurss-example\">ihr fragt — ptáte se</div><div class=\"kurss-example\">sie fragen — ptají se</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — odpovídám</div><div class=\"kurss-example\">du antwortest — odpovídáš</div><div class=\"kurss-example\">er antwortet — odpovídá</div><div class=\"kurss-example\">sie antwortet — odpovídá</div><div class=\"kurss-example\">wir antworten — odpovídáme</div><div class=\"kurss-example\">ihr antwortet — odpovídáte</div><div class=\"kurss-example\">sie antworten — odpovídají</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — počítám</div><div class=\"kurss-example\">du rechnest — počítáš</div><div class=\"kurss-example\">er rechnet — počítá</div><div class=\"kurss-example\">sie rechnet — počítá</div><div class=\"kurss-example\">wir rechnen — počítáme</div><div class=\"kurss-example\">ihr rechnet — počítáte</div><div class=\"kurss-example\">sie rechnen — počítají</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — kreslím</div><div class=\"kurss-example\">du zeichnest — kreslíš</div><div class=\"kurss-example\">er zeichnet — kreslí</div><div class=\"kurss-example\">sie zeichnet — kreslí</div><div class=\"kurss-example\">wir zeichnen — kreslíme</div><div class=\"kurss-example\">ihr zeichnet — kreslíte</div><div class=\"kurss-example\">sie zeichnen — kreslí</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — dělám</div><div class=\"kurss-example\">du tust — děláš</div><div class=\"kurss-example\">er tut — dělá</div><div class=\"kurss-example\">sie tut — dělá</div><div class=\"kurss-example\">wir tun — děláme</div><div class=\"kurss-example\">ihr tut — děláte</div><div class=\"kurss-example\">sie tun — dělají</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Struktura vět</h3>\n            <p class=\"kurss-lesson-intro\">V tázací větě stojí sloveso v němčině obvykle na prvním místě.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Příklady</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Přicházíš.</div><div class=\"kurss-example\">Kommst du? — Přicházíš?</div><div class=\"kurss-example\">Er singt. — Zpívá.</div><div class=\"kurss-example\">Singt er? — Zpívá?</div><div class=\"kurss-example\">Stehst du? — Stojíš?</div><div class=\"kurss-example\">Ja, ich stehe. — Ano, stojím.</div><div class=\"kurss-example\">Geht ihr? — Jdete?</div><div class=\"kurss-example\">Ja, wir gehen. — Ano, jdeme.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Otázky s „was“</h4>\n              <p>Pokud otázka začíná tázacím slovem, stojí sloveso v němčině obvykle hned za tázacím slovem.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Co děláš?</div><div class=\"kurss-example\">Was tut er? — Co dělá?</div><div class=\"kurss-example\">Was tut sie? — Co dělá?</div><div class=\"kurss-example\">Was tun sie? — Co dělají?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Zápor s „nicht“</h4>\n              <p>Pokud se zápor „nicht“ vztahuje ke slovesu, stojí v němčině obvykle za slovesem.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Nehraji.</div><div class=\"kurss-example\">Paul fragt nicht. — Pavel se neptá.</div><div class=\"kurss-example\">Er kommt nicht. — Nepřichází.</div><div class=\"kurss-example\">Sie singen nicht. — Nezpívají.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Věty z 2. lekce</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Hraješ?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ne, nehraji, pracuji.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Pavel se neptá, pracuje.</div><div class=\"kurss-example\">Arbeitest du? — Pracuješ?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ne, nepracuji, zpívám.</div><div class=\"kurss-example\">Was tut Paul? — Co dělá Pavel?</div><div class=\"kurss-example\">Er spielt. — Hraje.</div><div class=\"kurss-example\">Was tut Marie? — Co dělá Marie?</div><div class=\"kurss-example\">Sie singt. — Zpívá.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Pavel hraje, ale Marie zpívá.</div><div class=\"kurss-example\">Singt ihr? — Zpíváte?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ne, nezpíváme, pracujeme.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Co dělají Pavel a Marie?</div><div class=\"kurss-example\">Sie fragen. — Ptají se.</div><div class=\"kurss-example\">Sie antworten nicht. — Neodpovídají.</div><div class=\"kurss-example\">Wer arbeitet? — Kdo pracuje?</div><div class=\"kurss-example\">Wir arbeiten. — Pracujeme.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Počítáme a kreslíme.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Přicházejí, ptají se, odpovídají, pracují, hrají, zpívají a jdou.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Přednáška 2</h3>\n            <p class=\"kurss-lesson-intro\">Druhá přednáška: dialogy, slovíčka, výslovnost, gramatika a překlad.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogy / věty</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slovíčka</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — hrát si • hrát</div>\n                  <div class=\"kurss-example\">nein — ne</div>\n                  <div class=\"kurss-example\">nicht — ne</div>\n                  <div class=\"kurss-example\">arbeiten — pracovat</div>\n                  <div class=\"kurss-example\">fragen — ptát se</div>\n                  <div class=\"kurss-example\">was tut er? — co dělá?</div>\n                  <div class=\"kurss-example\">was tun sie? — co dělají?</div>\n                  <div class=\"kurss-example\">aber — ale</div>\n                  <div class=\"kurss-example\">antworten — odpovídat</div>\n                  <div class=\"kurss-example\">rechnen — počítat</div>\n                  <div class=\"kurss-example\">zeichnen — kreslit</div>\n                  <div class=\"kurss-example\">Marie — Marie</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vārdos ich, nicht, rechnen, zeichnen skaņu ch izrunā mīksti, apmēram tā, kā latviski vārdos: technika, Frīdrihs.</div><div class=\"kurss-example\">Vārdos arbeiten, zeichnen divskani ei izrunā apmēram kā latviešu plato e skaņu, kam seko i.</div><div class=\"kurss-example\">Līdzskaņu kopojumu sp izrunā kā šp: spielen (špīlen).</div><div class=\"kurss-example\">Darbības vārdā tun u izrunājams gari visās personās.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Koncovky na e</h4>\n                  <div class=\"lesson1-grammar-note\">Končí-li kmen slovesa na -t, -d nebo -chn, vkládá se při časování před koncovky -st a -t písmeno e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Otázka slovo</h4>\n                  <div class=\"lesson1-grammar-note\">V tázacích větách, které začínají tázacím slovem, například co?, kdo?, který?, proč? apod., stojí sloveso hned za tázacím slovem.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Co děláš?</div><div class=\"kurss-example\">Was tut er? — Co dělá?</div><div class=\"kurss-example\">Was tut sie? — Co dělá?</div><div class=\"kurss-example\">Was tun sie? — Co dělají?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Negace s nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Pokud se zápor nicht vztahuje ke slovesu, stojí nicht za slovesem.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Nepřichází.</div><div class=\"kurss-example\">Sie singen nicht. — Nezpívají.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Přeložit</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 2 pārtulkošanas kartīte\">\n                    <span class=\"lesson1-training-progress\">Lekcija 2 · Pārtulko: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kdo se ptá?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikněte na kartičku, abyste zobrazili německý překlad. Po zobrazení odpovědi dalším kliknutím přejdete na další kartičku.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Přednáška 6</h3>\n    <p class=\"kurss-lesson-intro\">Číslovky, množné číslo, přehlásky a tvary množného čísla podstatných jmen.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>1\\. Dialogy / věty</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>2\\. Slova</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — nachází se, je, leží</div><div class=\"kurss-example\">der Bleistift (bleištift) — tužka</div><div class=\"kurss-example\">einige (einige) — několik, někteří</div><div class=\"kurss-example\">hinlegen — položit</div><div class=\"kurss-example\">legt hin — pokládá</div><div class=\"kurss-example\">wieder (vīder) — znovu</div><div class=\"kurss-example\">aufmachen — otevřít</div><div class=\"kurss-example\">er macht auf — otevírá</div><div class=\"kurss-example\">anspitzen (anšpicen) — ořezat, naostřit</div><div class=\"kurss-example\">er spitzt an — ořezává, ostří</div><div class=\"kurss-example\">sich setzen — posadit se</div><div class=\"kurss-example\">setzt sich — sedá si</div><div class=\"kurss-example\">der Schlüssel (šlūsel) — klíč</div><div class=\"kurss-example\">das Fenster (fenster) — okno</div><div class=\"kurss-example\">die Tafel (dī tāfel) — tabule</div><div class=\"kurss-example\">der Garten — zahrada</div><div class=\"kurss-example\">der Löffel — lžíce</div><div class=\"kurss-example\">zählen (cēlen) — počítat</div><div class=\"kurss-example\">die Nadel — jehla</div><div class=\"kurss-example\">was ist das — co je to?</div><div class=\"kurss-example\">der Hammer — kladivo</div><div class=\"kurss-example\">die Hämmer — kladiva</div><div class=\"kurss-example\">der Deckel (dēr dekel) — víko</div><div class=\"kurss-example\">der Teller — talíř</div><div class=\"kurss-example\">der Wagen — vůz</div><div class=\"kurss-example\">der Schlitten — sáně</div><div class=\"kurss-example\">das Ding — věc</div><div class=\"kurss-example\">die Dinge — věci</div><div class=\"kurss-example\">wie sind die Dinge? — jaké jsou ty věci?</div><div class=\"kurss-example\">voll (fōl) — plný</div><div class=\"kurss-example\">leer (lēr) — prázdný</div><div class=\"kurss-example\">schwer (švēr) — těžký, obtížný</div><div class=\"kurss-example\">leicht — lehký, snadný</div><div class=\"kurss-example\">der Eimer — kbelík</div><div class=\"kurss-example\">wieviel (vīfīl) — kolik</div><div class=\"kurss-example\">wieviel Nadeln — kolik jehel</div><div class=\"kurss-example\">hier (hīr) — zde</div><div class=\"kurss-example\">dort — tam</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>3\\. Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä ir patskaņa a pārskanojums, un to izrunā kā īso vai garo šauro e.</div><div class=\"kurss-example\">Piemēri: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fāter), die Väter (dī fēter).</div><div class=\"kurss-example\">ü ir patskaņa u pārskanojums. To izrunājot, lūpas ļoti jāapaļo un jāmēģina ar apaļi veidotām lūpām izrunāt i.</div><div class=\"kurss-example\">Piemēri: fünf, der Schlüssel (šlūsel).</div><div class=\"kurss-example\">ö izrunā ar apaļi veidotām lūpām, mēģinot izrunāt e: der Löffel.</div><div class=\"kurss-example\">Divkāršots patskanis apzīmē garu patskani: leer (lēr).</div><div class=\"kurss-example\">Divskani eu izrunā kā oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>4\\. Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika a vysvětlení</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Salikta darbības vārda uzsvērtais priedēklis tagadnē atdalās no darbības vārda un stāv teikuma beigās.</div><div class=\"kurss-example\">Piemēri: hinlegen — er legt hin;</div><div class=\"kurss-example\">Skaitļa vārds viens ir visās trīs kārtās, ja to lieto ar lietvārdu: vīriešu kārtā ein, sieviešu kārtā eine, vidējā kārtā ein.</div><div class=\"kurss-example\">Piemēri: ein Schüler — eine ně; ein</div><div class=\"kurss-example\">Skaitļi: eins, zwei, drei, vier (fīr), fünf, sechs (zeks), sieben (zīben), acht, neun (noin), zehn (cēn).</div><div class=\"kurss-example\">Saitaiņa vācu valodā ir vienskaitļa un daudzskaitļa forma: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Norādāmais vietniekvārds tas latviešu valodā mainās skaitlī un kārtā, bet vācu valodā lieto vienu formu: das.</div><div class=\"kurss-example\">Piemēri: tas ir veseris — st ein r; to je adel; to er; n.</div><div class=\"kurss-example\">Der Wagen — štině se ě\" množném ímco v e tato ívat v i sle. ožném ibírají covku.</div><div class=\"kurss-example\">Vīriešu un vidējās kārtas lietvārdi ar galotni -er, -el, -en často nemají koncovku v množném čísle.</div><div class=\"kurss-example\">Piemēri: der Hammer — n.</div><div class=\"kurss-example\">Sieviešu kārtas lietvārdi ar galotni -el, -er vezměte -n v množném čísle.</div><div class=\"kurss-example\">Piemēri: die Nadel — die Nadeln • Die die Nadeln; die .</div><div class=\"kurss-example\">Izņēmumi: die Mutter (māte) — tter ); die r (dcera) (dcery).</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav: das ist ein Wagen — das sind Wagen; das ist eine Nadel Nadeln.</div><div class=\"kurss-example\">Stāstāmā teikumā izteicējs-sloveso stojí na druhém místě: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>5\\. Přeložit</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 6 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Přednáška 6 · Přeložil: 1 / 21</span><span class=\"lesson1-training-text\">Pavel bere tužku a kreslí.</span></button><p class=\"lesson1-training-hint\">Klikni na kartičku, abys viděl německý překlad. Po zobrazení odpovědi dalším kliknutím přejdeš na další kartičku.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Přednáška 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akuzativ, sitzen, fragen a</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>1\\. Dialogy / věty</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>2\\. Slova</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — sedět</div>\n        <div class=\"kurss-example\">fragen (frāgen) — ptát se</div>\n        <div class=\"kurss-example\">der Lehrer (dēr lērer) — učitel</div>\n        <div class=\"kurss-example\">gut (gūt) — dobře</div>\n        <div class=\"kurss-example\">wen (vēn) — koho?</div>\n        <div class=\"kurss-example\">loben — chválit</div>\n        <div class=\"kurss-example\">der Schüler (šūler) — žák</div>\n        <div class=\"kurss-example\">klein — malý</div>\n        <div class=\"kurss-example\">groß (grōs) — velký</div>\n        <div class=\"kurss-example\">die Lehrerin — učitelka</div>\n        <div class=\"kurss-example\">die Schülerin — žákyně</div>\n        <div class=\"kurss-example\">schlecht (šleht) — špatně</div>\n        <div class=\"kurss-example\">tadeln — kárat</div>\n        <div class=\"kurss-example\">oder (ōder) — nebo</div>\n        <div class=\"kurss-example\">das Kind (kint) — dítě</div>\n        <div class=\"kurss-example\">artig (ārtich) — hodný</div>\n        <div class=\"kurss-example\">die Mutter — matka</div>\n        <div class=\"kurss-example\">lieben (līben) — milovat</div>\n        <div class=\"kurss-example\">der Vater (fāter) — otec</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>3\\. Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz ir dubultots z skanis un izrunājams kā z: sitzen (zicen).</div>\n        <div class=\"kurss-example\">v vācu vārdos izrunā kā f: der Vater (fāter).</div>\n        <div class=\"kurss-example\">ß sauc par escet un izrunā kā latviešu s: groß (grōs), weiß (veis).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>4\\. Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ a akuzativ</h4><div class=\"lesson1-grammar-note\">V češtině odpovídá nominativ na otázky kdo? co?, zatímco akuzativ na otázky koho? co?</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vācu valodā nominatīvā jautājums ir wer? personām un was? priekšmetiem.</div><div class=\"kurss-example\">Akuzatīvā jautājums ir wen? personām un was? priekšmetiem.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Změna článků na akuzativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Fragen + akuzativ</h4><div class=\"lesson1-grammar-note\">Německé sloveso fragen vyžaduje akuzativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">- na závěr</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Daudz sieviešu kārtas vārdu atvasina ar galotni -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Místo slovesa</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stāstāmā teikumā darbības vārds stāv otrā vietā.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>5\\. Přeložit</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 5 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Přednáška 5 · Přeložil: 1 / 16</span><span class=\"lesson1-training-text\">Co miluje otec?</span></button><p class=\"lesson1-training-hint\">Klikni na kartičku, abys viděl německý překlad. Po zobrazení odpovědi dalším kliknutím přejdeš na další kartičku.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Přednáška 4</h3>\n            <p class=\"kurss-lesson-intro\">Akuzativ, nehmen, hinlegen, hinausgehen a přídavná jména.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>1\\. Dialogy / věty</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>2\\. Slova</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nēmen) — vzít</div><div class=\"kurss-example\">er nimmt (nimt) — on bere</div><div class=\"kurss-example\">der Federhalter (dēr fēderhalter) — násadka na pero</div><div class=\"kurss-example\">einen Federhalter — násadku na pero</div><div class=\"kurss-example\">zeigen — ukazovat</div><div class=\"kurss-example\">schwarz (švarc) — černý</div><div class=\"kurss-example\">weiß (veis) — bílý</div><div class=\"kurss-example\">die Feder (dī fēder) — pero</div><div class=\"kurss-example\">eine Feder — pero</div><div class=\"kurss-example\">spitz (špic) — špičatý</div><div class=\"kurss-example\">hinlegen — položit</div><div class=\"kurss-example\">legt hin — pokládá</div><div class=\"kurss-example\">das Mädchen (mētchen) — dívka</div><div class=\"kurss-example\">das Messer — nůž</div><div class=\"kurss-example\">ein Messer — nůž</div><div class=\"kurss-example\">scharf — ostrý</div><div class=\"kurss-example\">stumpf (štumpf) — tupý</div><div class=\"kurss-example\">dann — pak</div><div class=\"kurss-example\">hinaus — ven</div><div class=\"kurss-example\">hinausgehen — vyjít, jít ven é, v men, r r.</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>3\\. Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Galotnes -en, -er, -el jsou nepřízvučné, takže e v těchto koncovkách je slabě slyšitelné: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h vācu valodā var būt gan skaņa, gan garumzīme iepriekšējam patskanim.</div><div class=\"kurss-example\">Ja h ir garumzīme, to neizrunā kā skaņu: nehmen (nēmen).</div><div class=\"kurss-example\">Ja patskanim seko tikai viens līdzskanis, patskani izrunā gari: die (dī) Feder (fēder), den (dēn).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>4\\. Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akuzativ</h4><div class=\"lesson1-grammar-note\">V ženském a středním rodě je akuzativ stejný jako nominativ. Mění se pouze mužský rod.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Vzít</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Zájmena</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — na řadě muži</div><div class=\"kurss-example\">sie — ženská řada</div><div class=\"kurss-example\">es — d</div><div class=\"kurss-example\">daudzskaitlī — ředního as .</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Oddělitelná slovesa</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Přídavná jména</h4><div class=\"lesson1-grammar-note\">Pokud je přídavné jméno ve větě součástí přísudku, nemění se podle rodu ani čísla.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negace s nicht</h4><div class=\"lesson1-grammar-note\">Pokud nicht popírá přídavné jméno, stojí před tímto přídavným jménem.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Lietvārdi ar galotni -chen a -lein jsou ve středním pořadí: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>5\\. Přeložit</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 4 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Přednáška 4 · Přeložil: 1 / 16</span><span class=\"lesson1-training-text\">Dívka si vezme pírko.</span></button><p class=\"lesson1-training-hint\">Klikni na kartičku, abys viděl německý překlad. Po zobrazení odpovědi dalším kliknutím přejdeš na další kartičku.</p></div></div></details>",
  "kurssLesson3": "            <h3>Přednáška 3</h3>\n            <p class=\"kurss-lesson-intro\">Třetí přednáška: dialogy, slovíčka, výslovnost, gramatika a překlad.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogy / věty</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slovíčka</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kdo</div><div class=\"kurss-example\">was — co</div><div class=\"kurss-example\">hier — zde</div><div class=\"kurss-example\">dort — tam</div><div class=\"kurss-example\">der Tisch — stůl</div><div class=\"kurss-example\">ein Tisch — stůl</div><div class=\"kurss-example\">die Bank — lavička</div><div class=\"kurss-example\">eine Bank — lavička</div><div class=\"kurss-example\">liegen — ležet</div><div class=\"kurss-example\">liegt hier ein Buch? — leží zde kniha?</div><div class=\"kurss-example\">das Buch — kniha</div><div class=\"kurss-example\">ein Buch — kniha</div><div class=\"kurss-example\">hängen — viset</div><div class=\"kurss-example\">das Bild — obraz</div><div class=\"kurss-example\">ein Bild — obraz</div><div class=\"kurss-example\">die Tafel — tabule</div><div class=\"kurss-example\">eine Tafel — tabule</div><div class=\"kurss-example\">wie — jaký, jaká, jaké</div><div class=\"kurss-example\">ist — je</div><div class=\"kurss-example\">dick — tlustý, silný</div><div class=\"kurss-example\">das Heft — sešit</div><div class=\"kurss-example\">ein Heft — sešit</div><div class=\"kurss-example\">dünn — tenký</div><div class=\"kurss-example\">niedrig — nízký</div><div class=\"kurss-example\">hoch — vysoký</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Garo ī skaņu vācu valodā apzīmē ar ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">ck ir divkāršs k: dick (dikk).</div><div class=\"kurss-example\">Īpašības un apstākļu vārdos galotne -Lautem [ç]: niedrig.</div><div class=\"kurss-example\">Ja galotne -e (-ige), vyslovuje se g jako [g]: niedrige (nídrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Předmět věty</h4><div class=\"lesson1-grammar-note\">Podmět věty v němčině odpovídá na otázku wer? / was? a stojí v nominativu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ar wer? jautā pēc personām.</div><div class=\"kurss-example\">Ar was? jautā pēc priekšmetiem.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Články</h4><div class=\"lesson1-grammar-note\">V němčině mají podstatná jména tři rody: mužský, ženský a střední. Před podstatným jménem obvykle stojí člen. Člen se do češtiny zpravidla nepřekládá.</div><h5 class=\"lesson2-subtitle\">Noteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">vīriešu kārta — der</div><div class=\"kurss-example\">sieviešu kārta — die</div><div class=\"kurss-example\">vidējā kārta — das</div><div class=\"kurss-example\">Daudzskaitlī noteiktais artikuls visām trim kārtām ir die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nenoteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">vīriešu kārta — ein</div><div class=\"kurss-example\">sieviešu kārta — eine</div><div class=\"kurss-example\">vidējā kārta — ein</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Vlastní podstatná jména</h4><div class=\"lesson1-grammar-note\">Před vlastními jmény se člen zpravidla nepoužívá.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Místo slovesa</h4><div class=\"lesson1-grammar-note\">V oznamovací větě stojí časované sloveso na druhém místě.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Stehen / zástavní právo / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vāciski par priekšmetiem, kas stāv vertikāli, saka, ka priekšmets stāv:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Par priekšmetiem, kas atrodas horizontālā stāvoklī, saka, ka tie guļ:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Priekšmeti var arī karāties:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Přeložit</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 3 pārtulkošanas kartīte\"><span class=\"lesson1-training-progress\">Přednáška 3 · Přeložil: 1 / 22</span><span class=\"lesson1-training-text\">Počítáš?</span></button><p class=\"lesson1-training-hint\">Klikněte na kartičku, abyste zobrazili německý překlad. Po zobrazení odpovědi dalším kliknutím přejdete na další kartičku.</p></div></div></details>",
  "kurssLesson7": "            <h3>Přednáška 7</h3>\n            <p class=\"kurss-lesson-intro\">Sedmá přednáška: rozkazovací způsob, zdvořilostní forma a množné číslo.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>1\\. Dialogy / věty</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>2\\. Slova</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — zpívat</div><div class=\"kurss-example\">singe — zpívej</div><div class=\"kurss-example\">singt — zpívejte</div><div class=\"kurss-example\">singen Sie — zpívejte</div><div class=\"kurss-example\">das Lied (das līt) — píseň</div><div class=\"kurss-example\">Sie — Vy</div><div class=\"kurss-example\">zählen — počítat</div><div class=\"kurss-example\">das Fräulein (froilein) — slečna</div><div class=\"kurss-example\">der Müller — mlynář</div><div class=\"kurss-example\">öffnen — otevřít</div><div class=\"kurss-example\">das Fenster (fenster) — okno</div><div class=\"kurss-example\">alle — všichni</div><div class=\"kurss-example\">der Spiegel (špīgel) — zrcadlo</div><div class=\"kurss-example\">der Lappen — hadr, utěrka</div><div class=\"kurss-example\">der Spaten — rýč</div><div class=\"kurss-example\">der Besen — koště</div><div class=\"kurss-example\">die Schaufel — lopatka</div><div class=\"kurss-example\">die Schüssel — mísa</div><div class=\"kurss-example\">das Zimmer — pokoj</div><div class=\"kurss-example\">das Ufer (ūfer) — břeh</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>3\\. Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp vārda vai zilbes sākumā izrunā kā šp: der Spiegel (dēr špīgel).</div><div class=\"kurss-example\">sch izrunā kā latviešu š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">Divskani äu izrunā kā latviešu oi: das Fräulein (das froilein).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>4\\. Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Příkazový výraz</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pavēles izteiksme vienskaitļa 2. personā atbilst darbības vārda 2. personai vienskaitlī bez personu galotnes -st a přidáním</div><div class=\"kurss-example\">Piemēri: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Ļoti bieži galotne -mi často : geh!, mm!, tu!, ag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Příkaz v množném čísle</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pavēles forma 2. personā daudzskaitlī līdzinās tagadnes daudzskaitļa 2. personai, bet tiek lietota bez vietniekvārda.</div><div class=\"kurss-example\">Piemēri: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Adresový formulář se Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Uzrunas forma ar “Jūs” līdzinās daudzskaitļa 3. personai. Vietniekvārds Sie rakstāms ar lielo burtu un stāv pēc darbības vārda.</div><div class=\"kurss-example\">Piemēri: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>OTEVŘENO</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Darbības vārdam öffnen vieglākas izrunas dēļ 2. un 3. personā vienskaitlī un 2. personā daudzskaitlī starp celmu un galotni iesprauž e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>5\\. Übung / Cvičení</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 7 vingrinājuma kartīte\"><span class=\"lesson1-training-progress\">Přednáška 7 · Übung: 1/16</span><span class=\"lesson1-training-text\">Fragen — ptát se</span></button><p class=\"lesson1-training-hint\">Klepnutím na kartičku zobrazíš tvary rozkazovacího způsobu.</p></div></div></details>",
  "kurssLesson1": "            <h3>Přednáška 1</h3>\n            <p class=\"kurss-lesson-intro\">První přednáška: slovesa v přítomném čase, slovíčka, výslovnost, gramatika a překlad.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Slovesa v přítomném čase</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Slovesa a jejich časování v přítomném čase.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — přicházet</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>přicházím</span><span>du</span><strong>kommst</strong><span>přicházíš</span><span>er / sie</span><strong>kommt</strong><span>on / ona přichází</span><span>wir</span><strong>kommen</strong><span>přicházíme</span><span>ihr</span><strong>kommt</strong><span>přicházíte</span><span>sie / Sie</span><strong>kommen</strong><span>oni přicházejí / Vy přicházíte</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — jít</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>jdu</span><span>du</span><strong>gehst</strong><span>jdeš</span><span>er / sie</span><strong>geht</strong><span>on / ona jde</span><span>wir</span><strong>gehen</strong><span>jdeme</span><span>ihr</span><strong>geht</strong><span>jdete</span><span>sie / Sie</span><strong>gehen</strong><span>oni jdou / Vy jdete</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stát</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>stojím</span><span>du</span><strong>stehst</strong><span>stojíš</span><span>er / sie</span><strong>steht</strong><span>on / ona stojí</span><span>wir</span><strong>stehen</strong><span>stojíme</span><span>ihr</span><strong>steht</strong><span>stojíte</span><span>sie / Sie</span><strong>stehen</strong><span>oni stojí / Vy stojíte</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — zpívat</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>zpívám</span><span>du</span><strong>singst</strong><span>zpíváš</span><span>er / sie</span><strong>singt</strong><span>on / ona zpívá</span><span>wir</span><strong>singen</strong><span>zpíváme</span><span>ihr</span><strong>singt</strong><span>zpíváte</span><span>sie / Sie</span><strong>singen</strong><span>oni zpívají / Vy zpíváte</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Příklady</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Slovíčka</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Přibližná výslovnost slov je uvedena v závorkách českými písmeny. Stejný způsob zápisu se používá i v dalších přednáškách.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vīr) — my</div><div class=\"kurss-example\">Vārdā “wir” burts i tiek izrunāts gari.</div><div class=\"kurss-example\">kommen (komen) — přicházet</div><div class=\"kurss-example\">gehen (gē-jít</div><div class=\"kurss-example\">stehen (štē-stát</div><div class=\"kurss-example\">singen (zingen) — zpívat</div><div class=\"kurss-example\">du (dū) kommst — ty přicházíš</div><div class=\"kurss-example\">er (ēr) kommt — on přichází</div><div class=\"kurss-example\">sie (zī) kommt — ona přichází</div><div class=\"kurss-example\">wer (vēr) — kdo?</div><div class=\"kurss-example\">ja (jā) — ano</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Výslovnost</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vārdu pareiza izruna, apzīmēta latviešu burtiem, ir dota lekcijās.</div><div class=\"kurss-example\">Wir (vīr) — my. Ve slově wir se i vyslovuje dlouze.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Základní tvar slovesa. Infinitiv obvykle končí na -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Přítomné konce</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">Od infinitivu slovesa odstraň -en a přidej příslušnou koncovku. Příklad: kommen → komm + koncovka. kommen = infinitiv.</div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>noņem <span class=\"lesson1-ending-accent\">- en</span></strong><span>Kořen zůstává</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>Komunikace</strong><span>Kořen</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>Ukončit to</strong><span>E / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>Přijď</strong></div><div>komm + <span class=\"lesson1-ending-accent\">Ulice</span> = <strong>Comm</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>Kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Příklady</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Otázkové věty</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">V německé tázací větě stojí sloveso obvykle na prvním místě.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Latviešu valodā:<br>Tu nāc.<br>Vai tu nāc?</div><div class=\"kurss-example\">Vācu valodā:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ty přicházíš<br>kommst du? — přicházíš?</div><div class=\"kurss-example\">er singt — on zpívá<br>singt er? — zpívá?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Osobní rozdíl</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — on přichází</div><div class=\"kurss-example\">sie kommt — ona přichází</div><div class=\"kurss-example\">sie kommen — oni / ony přicházejí</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Přeložit</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 1 treniņa kartīte\">\n                    <span class=\"lesson1-training-progress\">Přednáška 1 · Přeložil: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Jdeš?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikněte na kartičku, abyste zobrazili německý překlad. Po zobrazení odpovědi dalším kliknutím přejdete na další kartičku.</p>\n                </div>\n              </div>\n            </details>"
};

